  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chercheur-Dœnopion-(Alchimiste).html&quot; title=&quot;Chercheur visionnaire&quot;&gt;Chercheur visionnaire&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chimiste-Enrag&#233;-(Alchimiste).html&quot; title=&quot;Chimiste enrag&#233;&quot;&gt;Chimiste enrag&#233;&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chimiste-Inspir&#233;-(Alchimiste).html&quot; title=&quot;Chimiste inspir&#233;&quot;&gt;Chimiste inspir&#233;&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chimiste-Spirituel-(Alchimiste).html&quot; title=&quot;Chimiste spirituel&quot;&gt;Chimiste spirituel&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chirurgien-(Alchimiste).html&quot; title=&quot;Chirurgien&quot;&gt;Chirurgien&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Collectionneur-(Alchimiste).html&quot; title=&quot;Collectionneur&quot;&gt;Collectionneur&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ectochimiste-(Alchimiste).html&quot; title=&quot;Ectochimiste&quot;&gt;Ectochimiste&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Explorateur-De-Cryptes-(Alchimiste).html&quot; title=&quot;Explorateur de cryptes&quot;&gt;Explorateur de cryptes&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Grenadier-(Alchimiste).html&quot; title=&quot;Grenadier&quot;&gt;Grenadier&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Hobgobelin-(Race).html&quot; title=&quot;Les hobgobelins&quot;&gt;Hobgobelin&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Homonculiste-(Alchimiste).html&quot; title=&quot;Homonculiste &quot;&gt;Homonculiste&lt;/a&gt; (FF)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Interrogateur-(Alchimiste).html&quot; title=&quot;Interrogateur&quot;&gt;Interrogateur&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Inventeur-Alchimiste-(Alchimiste).html&quot; title=&quot;Inventeur alchimiste&quot;&gt;Inventeur alchimiste&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-Clones-(Alchimiste).html&quot; title=&quot;Ma&#238;tre des clones&quot;&gt;Ma&#238;tre des clones&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Maraudeur-Ail&#233;-(Alchimiste).html&quot; title=&quot;Maraudeur ail&#233;&quot;&gt;Maraudeur ail&#233;&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gobelin-(Race).html&quot; title=&quot;Les gobelins&quot;&gt;Gobelin&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;tamorphe-(Alchimiste).html&quot; title=&quot;M&#233;tamorphe&quot;&gt;M&#233;tamorphe&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Porte-Peste-(Alchimiste).html&quot; title=&quot;Porte-peste&quot;&gt;Porte-peste&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Homme-Rat-(Race).html&quot; title=&quot;Les hommes-rats&quot;&gt;Homme-rat&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Psychonaute-(Alchimiste).html&quot; title=&quot;Psychonaute&quot;&gt;Psychonaute&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pyrobombardier-(Alchimiste).html&quot; title=&quot;Pyrobombardier&quot;&gt;Pyrobombardier&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gobelin-(Race).html&quot; title=&quot;Les gobelins&quot;&gt;Gobelin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;animateur-(Alchimiste).html&quot; title=&quot;R&#233;animateur&quot;&gt;R&#233;animateur&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Saboteur-(Alchimiste).html&quot; title=&quot;Saboteur&quot;&gt;Saboteur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gnome.html&quot; title=&quot;Les gnomes&quot;&gt;Gnome&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sapeur-Alchimique-(Alchimiste).html&quot; title=&quot;Sapeur alchimique&quot;&gt;Sapeur alchimique&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Trappeur-Alchimique-(Alchimiste).html&quot; title=&quot;Trappeur alchimique&quot;&gt;Trappeur alchimique&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Kobold-(Race).html&quot; title=&quot;Les kobolds&quot;&gt;Kobold&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vivisectioniste-(Alchimiste).html&quot; title=&quot;Vivisectioniste&quot;&gt;Vivisectioniste&lt;/a&gt; (AM)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la magie (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Magic/Art de la Magie&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUM.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;L’alchimiste interne &#233;tudie la m&#233;decine, les r&#233;gimes et le corps vivant pour se purifier dans l’espoir d’atteindre l’immortalit&#233; &#224; l’aide de d&#233;coctions alchimiques et d’un bon contr&#244;le de l’&#233;nergie vitale. Les alchimistes internes d&#233;veloppent des aptitudes physiques inhabituelles gr&#226;ce aux immenses connaissances qu’ils poss&#232;dent sur le fonctionnement de leur corps. L’alchimiste interne poss&#232;de les aptitudes de classe suivantes.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Ma&#238;trise de la respiration&lt;a class=&quot;headeranchor&quot; id=&quot;Ma&#238;trise_de_la_respiration_0&quot; href=&quot;#Ma&#238;trise_de_la_respiration_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 1, l’alchimiste interne apprend &#224; contr&#244;ler son souffle et le flot d’&#233;nergie vitale de son corps. M&#234;me sans pr&#233;paration, il peut retenir son souffle pendant un nombre de minutes &#233;gal &#224; sa valeur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt; (ensuite, il doit faire des tests de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt; ou suffoquer). S’il passe une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Complexe.html&quot; title=&quot;Action complexe&quot;&gt;action complexe&lt;/a&gt; &#224; se pr&#233;parer, il peut faire passer cette dur&#233;e &#224; une heure par point de Constitution.&lt;br /&gt;&lt;br /&gt;L’&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;alchimiste&lt;/a&gt; peut survivre deux fois plus longtemps que la normale sans nourriture ni eau avant de recevoir ses premiers malus. Il peut se placer en &#233;tat d’animation suspendue par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Mouvement.html&quot; title=&quot;Action de mouvement&quot;&gt;action de mouvement&lt;/a&gt;. Il est alors &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Inconscient.html&quot; title=&quot;Inconscient&quot;&gt;inconscient&lt;/a&gt; et semble mort. Il se r&#233;veille &#224; une date pr&#233;d&#233;termin&#233;e ou en r&#233;ponse &#224; une condition qu’il a fix&#233;e au moment d’entrer en animation suspendue. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#LANCERIMPROVISE&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;lancer improvis&#233;&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Dons suppl&#233;mentaires&lt;a class=&quot;headeranchor&quot; id=&quot;Dons_suppl&#233;mentaires_1&quot; href=&quot;#Dons_suppl&#233;mentaires_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;L’alchimiste interne peut choisir &lt;a class=&quot;pagelink&quot; href=&quot;Arme-De-Pr&#233;dilection.html&quot; title=&quot;Arme de pr&#233;dilection&quot;&gt;Arme de pr&#233;dilection&lt;/a&gt; (mains nues), &lt;a class=&quot;pagelink&quot; href=&quot;Coup-&#201;tourdissant.html&quot; title=&quot;Coup &#233;tourdissant&quot;&gt;Coup &#233;tourdissant&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Ki-Suppl&#233;mentaire.html&quot; title=&quot;Ki suppl&#233;mentaire&quot;&gt;Ki suppl&#233;mentaire&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;flexes-Surhumains.html&quot; title=&quot;R&#233;flexes surhumains&quot;&gt;R&#233;flexes surhumains&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Combat-&#192;-Mains-Nues.html&quot; title=&quot;Science du combat &#224; mains nues&quot;&gt;Science du combat &#224; mains nues&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Critique.html&quot; title=&quot;Science du critique&quot;&gt;Science du critique&lt;/a&gt; (mains nues), &lt;a class=&quot;pagelink&quot; href=&quot;Science-De-Linitiative.html&quot; title=&quot;Science de l&amp;#39;initiative&quot;&gt;Science de l’initiative&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Vigilance.html&quot; title=&quot;Vigilance&quot;&gt;Vigilance&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Vigueur-Surhumaine.html&quot; title=&quot;Vigueur surhumaine&quot;&gt;Vigueur surhumaine&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Volont&#233;-De-Fer.html&quot; title=&quot;Volont&#233; de fer&quot;&gt;Volont&#233; de fer&lt;/a&gt; &#224; la place d’une &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;d&#233;couverte alchimique&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;R&#233;sistance aux maladies&lt;a class=&quot;headeranchor&quot; id=&quot;R&#233;sistance_aux_maladies_2&quot; href=&quot;#R&#233;sistance_aux_maladies_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 3, l’alchimiste interne gagne un bonus &#224; tous les &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jets de sauvegarde&lt;/a&gt; contre la &lt;a class=&quot;pagelink&quot; href=&quot;Maladies.html&quot; title=&quot;maladie&quot;&gt;maladie&lt;/a&gt;. Ce bonus est &#233;gal &#224; son bonus de classe contre les &lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html&quot; title=&quot;Les poisons  &quot;&gt;poisons&lt;/a&gt;. Quand il gagne le pouvoir de classe &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#IMMUNITEAUXPOISONS&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;immunit&#233; aux poisons&lt;/a&gt;, il devient &#233;galement immunis&#233; contre les maladies.&lt;br /&gt;&lt;br /&gt;Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#ALCHIMIERAPIDE&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;alchimie rapide&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Esquive instinctive&lt;a class=&quot;headeranchor&quot; id=&quot;Esquive_instinctive_3&quot; href=&quot;#Esquive_instinctive_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&#192; partir du niveau 6, un alchimiste interne peut r&#233;agir au danger avant que ses sens ne le per&#231;oivent. Il ne peut plus &#234;tre &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Prisaud&#233;pourvu.html&quot; title=&quot;Pris au d&#233;pourvu&quot;&gt;pris au d&#233;pourvu&lt;/a&gt; et il ne perd plus son bonus de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt; &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; si son attaquant est &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Invisible.html&quot; title=&quot;Invisible&quot;&gt;invisible&lt;/a&gt;. Toutefois, il perd tout de m&#234;me son bonus de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt; &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; s’il est &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Immobilis&#233;.html&quot; title=&quot;Immobilis&#233;&quot;&gt;immobilis&#233;&lt;/a&gt; ou si un adversaire r&#233;ussit &#224; le &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Sp&#233;ciales#Feinte.html&quot; title=&quot;feinte&quot;&gt;feinter&lt;/a&gt; (voir le &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt;). Si l’alchimiste interne poss&#232;de d&#233;j&#224; l’&lt;a class=&quot;pagelink&quot; href=&quot;Roublard#Esquiveinstinctive.html&quot; title=&quot;esquive instinctive&quot;&gt;esquive instinctive&lt;/a&gt; gr&#226;ce &#224; une autre classe, il gagne aussit&#244;t &lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html#ESQUIVEINSTINCTIVESUPERIEURE&quot; title=&quot;Le roublard&quot;&gt;esquive instinctive sup&#233;rieure&lt;/a&gt; (comme un &lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html&quot; title=&quot;Le roublard&quot;&gt;roublard&lt;/a&gt;).&lt;br /&gt;&lt;br /&gt;Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#EMPOISONNEMENTRAPIDE&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;empoisonnement rapide&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;D&#233;couvertes&lt;a class=&quot;headeranchor&quot; id=&quot;D&#233;couvertes_4&quot; href=&quot;#D&#233;couvertes_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les d&#233;couvertes suivantes viennent compl&#233;ter l’arch&#233;type de l’alchimiste interne : &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#COGNATOGENE&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;cognatog&#232;ne&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#COGNATOGENESUPERIEUR&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;cognatog&#232;ne sup&#233;rieur&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#ELIXIRDEVIE&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;&#233;lixir de vie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#GRANDCOGNATOGENE&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;grand cognatog&#232;ne&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#GUERISONSPONTANEE&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;gu&#233;rison spontan&#233;e&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#MOMIFICATION&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;momification&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#RETARDERLEDEPART&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;retarder le d&#233;part&lt;/a&gt;.
